CREATE TABLE {{prefix}}migrations (version INTEGER PRIMARY KEY NOT NULL, identity TEXT NOT NULL);

CREATE TABLE {{prefix}}vaults (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, revision TEXT NOT NULL, archived INTEGER NOT NULL CHECK(archived IN (0,1)), generation TEXT NOT NULL, stamp INTEGER NOT NULL);
CREATE TABLE {{prefix}}settings (vaultId TEXT PRIMARY KEY NOT NULL REFERENCES {{prefix}}vaults(id), revision TEXT NOT NULL, incomeAccountId TEXT, expenseAccountId TEXT, FOREIGN KEY(vaultId,incomeAccountId) REFERENCES {{prefix}}accounts(vaultId,id), FOREIGN KEY(vaultId,expenseAccountId) REFERENCES {{prefix}}accounts(vaultId,id));
CREATE TABLE {{prefix}}change_records (vaultId TEXT NOT NULL REFERENCES {{prefix}}vaults(id), id TEXT NOT NULL, targetId TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(vaultId,id));
CREATE INDEX {{prefix}}history_target ON {{prefix}}change_records(vaultId,targetId);
CREATE TABLE {{prefix}}accounts (vaultId TEXT NOT NULL REFERENCES {{prefix}}vaults(id), id TEXT NOT NULL, name TEXT NOT NULL, revision TEXT NOT NULL, balanceRevision TEXT NOT NULL, nature TEXT NOT NULL CHECK(nature IN ('asset','liability')), currency TEXT NOT NULL CHECK(length(currency)=3), archived INTEGER NOT NULL CHECK(archived IN (0,1)), hasTransactions INTEGER NOT NULL CHECK(hasTransactions IN (0,1)), PRIMARY KEY(vaultId,id), UNIQUE(vaultId,name));
CREATE TABLE {{prefix}}categories (vaultId TEXT NOT NULL REFERENCES {{prefix}}vaults(id), id TEXT NOT NULL, revision TEXT NOT NULL, name TEXT NOT NULL, parentId TEXT, archived INTEGER NOT NULL CHECK(archived IN (0,1)), PRIMARY KEY(vaultId,id), FOREIGN KEY(vaultId,parentId) REFERENCES {{prefix}}categories(vaultId,id));
CREATE UNIQUE INDEX {{prefix}}category_siblings ON {{prefix}}categories(vaultId,coalesce(parentId,''),name);
CREATE TABLE {{prefix}}transactions (vaultId TEXT NOT NULL REFERENCES {{prefix}}vaults(id), id TEXT NOT NULL, revision TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('income','expense','transfer','adjustment')), occurredOn TEXT NOT NULL, memo TEXT, accountId TEXT, amountMinor INTEGER, sourceAccountId TEXT, sourceAmountMinor INTEGER, destinationAccountId TEXT, destinationAmountMinor INTEGER, PRIMARY KEY(vaultId,id), FOREIGN KEY(vaultId,accountId) REFERENCES {{prefix}}accounts(vaultId,id), FOREIGN KEY(vaultId,sourceAccountId) REFERENCES {{prefix}}accounts(vaultId,id), FOREIGN KEY(vaultId,destinationAccountId) REFERENCES {{prefix}}accounts(vaultId,id), CHECK((kind='transfer' AND accountId IS NULL AND amountMinor IS NULL AND sourceAccountId IS NOT NULL AND destinationAccountId IS NOT NULL AND sourceAccountId<>destinationAccountId AND sourceAmountMinor IS NOT NULL AND destinationAmountMinor IS NOT NULL AND sourceAmountMinor>0 AND destinationAmountMinor>0) OR (kind<>'transfer' AND accountId IS NOT NULL AND amountMinor IS NOT NULL AND sourceAccountId IS NULL AND sourceAmountMinor IS NULL AND destinationAccountId IS NULL AND destinationAmountMinor IS NULL)), CHECK(amountMinor IS NULL OR (typeof(amountMinor)='integer' AND amountMinor BETWEEN -9007199254740991 AND 9007199254740991)), CHECK(sourceAmountMinor IS NULL OR (typeof(sourceAmountMinor)='integer' AND sourceAmountMinor BETWEEN 1 AND 9007199254740991)), CHECK(destinationAmountMinor IS NULL OR (typeof(destinationAmountMinor)='integer' AND destinationAmountMinor BETWEEN 1 AND 9007199254740991)), CHECK(kind='transfer' OR (kind='income' AND amountMinor>0) OR (kind IN ('expense','adjustment') AND amountMinor<>0)));
CREATE INDEX {{prefix}}transaction_account ON {{prefix}}transactions(vaultId,accountId);
CREATE INDEX {{prefix}}transaction_source ON {{prefix}}transactions(vaultId,sourceAccountId);
CREATE INDEX {{prefix}}transaction_destination ON {{prefix}}transactions(vaultId,destinationAccountId);
CREATE INDEX {{prefix}}transaction_date ON {{prefix}}transactions(vaultId,occurredOn);
CREATE TABLE {{prefix}}category_assignments (vaultId TEXT NOT NULL, transactionId TEXT NOT NULL, categoryId TEXT NOT NULL, amountMinor INTEGER NOT NULL CHECK(typeof(amountMinor)='integer' AND amountMinor<>0 AND amountMinor BETWEEN -9007199254740991 AND 9007199254740991), origin TEXT NOT NULL CHECK(origin IN ('explicit','inferred')), PRIMARY KEY(vaultId,transactionId,categoryId), FOREIGN KEY(vaultId,transactionId) REFERENCES {{prefix}}transactions(vaultId,id) ON DELETE CASCADE, FOREIGN KEY(vaultId,categoryId) REFERENCES {{prefix}}categories(vaultId,id));
CREATE TABLE {{prefix}}transaction_relations (vaultId TEXT NOT NULL, sourceId TEXT NOT NULL, targetTransactionId TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('refund_of','fee_for')), PRIMARY KEY(vaultId,sourceId,targetTransactionId,kind), FOREIGN KEY(vaultId,sourceId) REFERENCES {{prefix}}transactions(vaultId,id) ON DELETE CASCADE, FOREIGN KEY(vaultId,targetTransactionId) REFERENCES {{prefix}}transactions(vaultId,id) ON DELETE CASCADE, CHECK(sourceId<>targetTransactionId));
CREATE INDEX {{prefix}}relation_target ON {{prefix}}transaction_relations(vaultId,targetTransactionId);
CREATE VIEW {{prefix}}category_paths AS
SELECT c.vaultId,c.id,c.revision,c.name,c.parentId,c.archived,c.name AS path FROM {{prefix}}categories c WHERE c.parentId IS NULL
UNION ALL SELECT c.vaultId,c.id,c.revision,c.name,c.parentId,c.archived,p.name || ' / ' || c.name FROM {{prefix}}categories c JOIN {{prefix}}categories p ON c.vaultId=p.vaultId AND c.parentId=p.id WHERE p.parentId IS NULL
UNION ALL SELECT c.vaultId,c.id,c.revision,c.name,c.parentId,c.archived,g.name || ' / ' || p.name || ' / ' || c.name FROM {{prefix}}categories c JOIN {{prefix}}categories p ON c.vaultId=p.vaultId AND c.parentId=p.id JOIN {{prefix}}categories g ON p.vaultId=g.vaultId AND p.parentId=g.id WHERE g.parentId IS NULL;
